// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.24;

/// INTERFACES
import {IUFarmFund} from "./IUFarmFund.sol";

/// CONTRACTS
import {UFarmCoreLink} from "../../shared/UFarmCoreLink.sol";

/// LIBRARIES
import {SafeOPS} from "../../shared/SafeOPS.sol";

/**
 * @title IFundFactory interface
 * @author https://ufarm.digital/
 * @notice Interface for the FundFactory contract
 */
interface IFundFactory {
    /**
     * @notice Creates a new fund
     * @param _manager The manager of the fund
     * @param _salt The salt for the fund
     * @return fund The address of the new fund
     */
    function createFund(address _manager, bytes32 _salt) external returns (address fund);
}

/**
 * @title FundFactory contract
 * @author https://ufarm.digital/
 * @notice Deployer of new funds
 * @dev Needs to be initialized with UFarmCore address
 */
contract FundFactory is IFundFactory, UFarmCoreLink {
    /**
     * @dev Reverts if caller is not the Core
     */
    error CallerIsNotCore();

    // Beacon is UUPS upgradeable proxy address, implementation can be upgraded if needed
    address public immutable fundImplBeacon;

    constructor(address _ufarmCore, address _fundImplBeacon) {
        __init__UFarmCoreLink(_ufarmCore);
        fundImplBeacon = _fundImplBeacon;
    }

    /**
     * @inheritdoc IFundFactory
     */
    function createFund(address _manager, bytes32 _salt) external onlyLinked returns (address fund) {
        if (ufarmCore() != msg.sender) revert CallerIsNotCore();
        return SafeOPS._safeBeaconCreate2Deploy(fundImplBeacon, _salt, _getInitFundCall(_manager));
    }

    function getFundBySalt(address _manager, bytes32 _salt) public view returns (address fund) {
        return SafeOPS.computeBeaconProxyAddress(fundImplBeacon, _salt, _getInitFundCall(_manager));
    }

    function _getInitFundCall(address _manager) internal view returns (bytes memory) {
        return abi.encodeCall(IUFarmFund.__init_UFarmFund, (_manager, ufarmCore()));
    }
}

contracts/main/contracts/fund/IUFarmFund.content:
// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.24;

/**
 * @title IUFarmFund interface
 * @author https://ufarm.digital/
 * @notice Fund interface for the UFarm protocol
 */
interface IUFarmFund {
    /**
     * Possible statuses of the fund
     */
    enum FundStatus {
        Approved,
        Active,
        Terminated,
        Blocked
    }

    /**
     * @notice Struct for storing the fund member invitation
     * @param invitee - address of the invitee
     * @param permissionsMask - masked permissions of the invitee
     * @param deadline - deadline for the invitee to accept the invitation
     */
    struct FundMemberInvitation {
        address invitee;
        uint256 permissionsMask;
        uint256 deadline;
    }

    /**
     * @notice Reverts if the fund is not in the required status
     * @param requiredStatus - required status of the fund
     * @param currentStatus - current status of the fund
     */
    error WrongFundStatus(FundStatus requiredStatus, FundStatus currentStatus);

    /**
     * @notice Returns the current status of the fund
     */
    function status() external view returns (FundStatus);

    /**
     * @notice Returns the address of the UFarmCore contract
     */
    function ufarmCore() external view returns (address);

    /**
     * @notice Changes the status of the fund
     * @param newStatus New status of the fund
     */
    function changeStatus(FundStatus newStatus) external;

    /**
     * @notice Returns `true` if the pool is been managed by the fund
     * @param _pool - address of the pool to be checked
     */
    function isPool(address _pool) external view returns (bool);

    /**
     * @notice Initializes the fund, gives full permissions to the owner
     * @param _owner - fund owner
     * @param _ufarmCore - address of the UFarmCore contract
     */
    function __init_UFarmFund(address _owner, address _ufarmCore) external;
}

contracts/main/contracts/permissions/UFa.content:
// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.24;

import {UFarmErrors} from "../../shared/UFarmErrors.sol";

/**
 * @title UFarmPermissionsModel contract
 * @author https://ufarm.digital/
 * @notice Contract that implements permissions model for UFarm contracts
 */
abstract contract UFarmPermissionsModel {
    uint256 internal constant _FULL_PERMISSIONS_MASK = type(uint256).max;
    mapping(address => uint256) internal _accountMask;

    // EVENTS
    event PermissionsUpdated(address account, uint256 newPermissions);

    // ERRORS
    error PermissionAlreadyGranted(address account, uint256 permissions);

    // MODIFIERS
    /**
     * @notice Reverts if account has no required permissions
     * @param account - address to check permissions
     * @param permission1 - first permission to check
     * @param permission2 - second permission to check
     */
    modifier shouldHaveTwoPermissions(
        address account,
        uint8 permission1,
        uint8 permission2
    ) {
        _checkForPermissions(account, _twoPermissionsToMask(permission1, permission2));
        _;
    }

    // PUBLIC

    /**
     * @notice Returns 'true' if account has required permission, 'false' otherwise
     * @param account - address to check permissions
     * @param permissionToCheck - permission to check
     */
    function hasPermission(address account, uint8 permissionToCheck) external view virtual returns (bool) {
        return _hasPermission(account, permissionToCheck);
    }

    /**
     * @notice Returns mask of two persimssions
     * @param permission1 - First permission
     * @param permission2 - Second permission
     */
    function twoPermissionsToMask(uint8 permission1, uint8 permission2) external view virtual returns (uint256 mask) {
        return _twoPermissionsToMask(permission1, permission2);
    }

    /**
     * @notice Returns 'true' if account has required permissions mask, 'false' otherwise
     * @param account - address to check permissions
     * @param permissionsToCheck - permissions mask to compare with
     */
    function hasPermissionsMask(address account, uint256 permissionsToCheck) external view virtual returns (bool) {
        return __hasPermissions(_accountMask[account], permissionsToCheck);
    }

    /**
     * @notice Reverts if account has no required permissions mask
     * @param account - address to check permissions
     * @param permissionsToCheck - permissions mask to compare with
     */
    function checkForPermissionsMask(address account, uint256 permissionsToCheck) external view virtual {
        _checkForPermissions(account, permissionsToCheck);
    }

    // INTERNAL SETTERS

    function _updatePermissions(address account, uint256 newPermissions) internal {
        if (_accountMask[account] != newPermissions) {
            _accountMask[account] = newPermissions;
            emit PermissionsUpdated(account, newPermissions);
        } else {
            revert PermissionAlreadyGranted(account, newPermissions);
        }
    }

    // INTERNAL CHECKS

    function _checkForPermissions(address account, uint256 permissions) internal view {
        if (!__hasPermissions(_accountMask[account], permissions)) {
            revert UFarmErrors.NonAuthorized();
        }
    }

    // INTERNAL GETTERS

    function _hasPermission(address account, uint8 permissionToCheck) internal view returns (bool) {
        return (_accountMask[account] & (1 << permissionToCheck)) != 0;
    }

    function _maskHasPermission(uint256 mask, uint8 permissionToCheck) internal pure returns (bool) {
        return (mask & (1 << permissionToCheck)) != 0;
    }

    function _hasPermissionMask(address account, uint256 permissionToCheck) internal view returns (bool) {
        return (_accountMask[account] & permissionToCheck) == permissionToCheck;
    }

    function _isPermissionDiff(uint8 permission, uint256 mask1, uint256 mask2) internal pure returns (bool) {
        return ((mask1 & (1 << permission)) != (mask2 & (1 << permission)));
    }

    function _permissionToMask(uint8 permission) internal pure returns (uint256 mask) {
        return (1 << permission);
    }

    function _twoPermissionsToMask(uint8 permission1, uint8 permission2) internal pure returns (uint256 mask) {
        return (1 << permission1) | (1 << permission2);
    }

    function __hasPermissions(uint256 accountPermissions, uint256 mask) private pure returns (bool) {
        return (accountPermissions & mask) == mask;
    }

    uint256[50] private __gap;
}

